/// <summary>
/// VendInvoiceInfoTable table extension
/// </summary>
[ExtensionOf(tableStr(VendInvoiceInfoTable))]
final class METVendInvoiceInfoTable_Extension
{
}

Method.Source:
    /// <summary>
    /// validate if document can be submitted to workflow
    /// </summary>
    /// <param name = "workflowType">Workflow type</param>
    /// <returns>Return true if can submit else false</returns>
    public boolean canSubmitToWorkflow(str workflowType)
    {
        boolean ret = next canSubmitToWorkflow(workflowType);

        return ret && (this.purchTable().isInterCompanyOrder() || this.METClaimInvoice ||
                      (this.MetImportAmount && (this.displayMetVariance() == 0 || this.displayMETVarInTolerance())));
    }

    /// <summary>
    /// calculate markup totals
    /// </summary>
    /// <returns>totals container</returns>
    public container metMarkupTotals()
    {
        VendInvoiceInfoLine metVendInvoiceInfoLine;
        MarkupTrans         metMarkupTrans;
        Amount              metTotalTaxAmount, metTotalAmount, metAmount;

        while select metMarkupTrans
            join metVendInvoiceInfoLine
                where metMarkupTrans.TransTableId          == tableNum(VendInvoiceInfoLine) &&
                      metMarkupTrans.TransRecId            == metVendInvoiceInfoLine.RecId &&
                      metVendInvoiceInfoLine.ParmId        == this.ParmId &&
                      metVendInvoiceInfoLine.TableRefId    == this.TableRefId
        {
            metAmount = Markup::calcMarkupAmount(metMarkupTrans, metVendInvoiceInfoLine.ReceiveNow, metVendInvoiceInfoLine.LineAmount, 0,
                metVendInvoiceInfoLine.inclTax(), NoYes::Yes, metMarkupTrans.CurrencyCode, metMarkupTrans.TransDate,
                                     0, 0, null, false, 0, '', false, false);

            metTotalTaxAmount  += Tax::calcTaxAmount(metMarkupTrans.TaxGroup, metMarkupTrans.TaxItemGroup, metMarkupTrans.TransDate,
                metMarkupTrans.CurrencyCode, metAmount, TaxModuleType::PurchInvoice);

            metTotalAmount += metAmount;
        }

        return [metTotalAmount, metTotalTaxAmount];
    }

    /// <summary>
    /// Line amounts
    /// </summary>
    /// <returns>line amounts</returns>
    public container metlineAmounts()
    {
        PurchTotals     metPurchTotals;

        metPurchTotals = PurchTotals::newParmTable(this, PurchUpdate::All, this.ParmId, '', this.Ordering);
        metPurchTotals.calc();

        return [metPurchTotals.purchBalance(), metPurchTotals.purchTaxTotal()];
    }

    /// <summary>
    /// Display method to calculate GST variance
    /// </summary>
    /// <returns>GST variance</returns>
    public display MetGSTVariance displayMetGSTVariance()
    {
        Amount metTotalMarkupTax, metTotalMarkupAmount;
        Amount metTotalLineTax, metTotalLineAmount;

        [metTotalMarkupAmount, metTotalMarkupTax] = this.metMarkupTotals();
        [metTotalLineAmount, metTotalLineTax]     = this.metLineAmounts();

        return this.MetImportGST - (metTotalLineTax - metTotalMarkupTax);
    }

    /// <summary>
    /// Display method to calculate variance
    /// </summary>
    /// <returns>Variance</returns>
    public display MetVariance displayMetVariance()
    {
        Amount metTotalMarkupTax, metTotalMarkupAmount;
        Amount metTotalLineTax, metTotalLineAmount;

        [metTotalMarkupAmount, metTotalMarkupTax] = this.metMarkupTotals();
        [metTotalLineAmount, metTotalLineTax]     = this.metLineAmounts();

        return this.MetImportAmount - (metTotalLineAmount + (metTotalLineTax - metTotalMarkupTax));
    }

    /// <summary>
    /// Variance tolerance
    /// </summary>
    /// <returns>tolerance</returns>
    public display MetVarInTol displayMETVarInTolerance()
    {
        MetVariance metVariance = this.displayMetVariance();

        return metVariance && metVariance <= VendParameters::find().ExtendedPriceToleranceAmount && metVariance >= -VendParameters::find().ExtendedPriceToleranceAmount;
    }

    /// <summary>
    /// Finds claim lines
    /// </summary>
    /// <returns>True if claim line exists; otherwise false</returns>
    public display MetClaimExist displayMETHasClaimLines()
    {
        VendInvoiceInfoLine metVendInvoiceInfoLine;

        select count(RecId) from metVendInvoiceInfoLine
            where
                metVendInvoiceInfoLine.ParmId          == this.ParmId &&
                metVendInvoiceInfoLine.TableRefId      == this.TableRefId &&
                metVendInvoiceInfoLine.MetClaimLine    == NoYes::Yes;

        return metVendInvoiceInfoLine.RecId > 0;
    }
